from pathlib import Path
import re
base=Path('/home/bob/books/Second_Generation')
full=(base/'SECOND_GENERATION_FULL_MANUSCRIPT.md').read_text()
allc=(base/'SECOND_GENERATION_COMPLETE_WITH_ALL_CHAPTERS.md').read_text()
toc=(base/'SECOND_GENERATION_COMPLETE_WITH_INTRO_AND_TOC.md').read_text()
rew_dir=base/'rewrite'
chap_re=re.compile(r'^## Chapter (\d+) — (.+)$', re.M)
toc_re=re.compile(r'^Chapter (\d+) – (.+)$', re.M)
full_chaps={int(n):t for n,t in chap_re.findall(full)}
all_chaps=[(int(n),t) for n,t in chap_re.findall(allc)]
# de-dupe taking non-slug if repeated second occurrence; keep all for analysis
all_by_num={}
all_dupes={}
for n,t in all_chaps:
    all_dupes.setdefault(n,[]).append(t)
    if n not in all_by_num or '_' not in t:
        all_by_num[n]=t

toc_chaps={int(n):t for n,t in toc_re.findall(toc)}
rewrites=[]
for p in sorted(rew_dir.glob('Chapter_*_Rewrite.md')):
    txt=p.read_text()
    m=chap_re.search(txt)
    if m:
        rewrites.append((int(m.group(1)),m.group(2),p.name,len(txt.splitlines()),len(txt.split())))
print('TITLE MISMATCHES TOC vs FULL:')
for n in sorted(full_chaps):
    ft=full_chaps[n]
    tt=toc_chaps.get(n)
    if tt!=ft:
        print(f'{n}: FULL={ft!r} | TOC={tt!r}')
print('\nDUPLICATE TITLE PAIRS IN COMPLETE_WITH_ALL_CHAPTERS:')
for n,titles in sorted(all_dupes.items()):
    if len(titles)>1:
        print(f'{n}: {titles[0]!r} || {titles[1]!r}')
print('\nREWRITE CHAPTERS:')
for row in rewrites:
    print(row)
print('\nREWRITE COVERAGE:', [n for n,_,_,_,_ in rewrites])
